import {readFileSync} from 'node:fs';
import {pairedStats,classifyRatio,median} from "/Users/ilyagulya/Projects/My/bend/evals/selfhost_corpus_calibration.ts";
const triads=JSON.parse(readFileSync(process.argv[2]!,'utf8'));
const protocol=JSON.parse(readFileSync(process.argv[3]!,'utf8')),limit=protocol.selected.costGate;
const result:any={schemaVersion:1,triads};
for(const [variant,baseline] of [['C','A'],['C','B'],['B','A']]){
 const comparison:any={};
 for(const metric of ['checkerCpuMs','checkerWallMs','footprintBytes','rssBytes']){
  const a=triads.map((t:any)=>t[baseline][metric]),c=triads.map((t:any)=>t[variant][metric]);
  const statistics=pairedStats(a,c);comparison[metric]={...statistics,direction:classifyRatio(statistics.ci95,.02)};
 }
 comparison.medianFootprintRatio=median(triads.map((t:any)=>t[variant].footprintBytes))!/median(triads.map((t:any)=>t[baseline].footprintBytes))!;
 result[variant+'_over_'+baseline]=comparison;
}
result.costGate={cpuCAatMostPoint97:result.C_over_A.checkerCpuMs.geometricMeanRatio<=limit.geometricCpu_C_over_A_atMost,cpuCBatMost1Point02:result.C_over_B.checkerCpuMs.geometricMeanRatio<=limit.geometricCpu_C_over_B_atMost,everyCpuCAfaster:triads.every((t:any)=>t.C.checkerCpuMs/t.A.checkerCpuMs<limit.everyCpuPair_C_over_A_below),wallCAatMost1:result.C_over_A.checkerWallMs.geometricMeanRatio<=limit.geometricWall_C_over_A_atMost,medianFootCAatMost1:result.C_over_A.medianFootprintRatio<=limit.medianFootprint_C_over_A_atMost,geometricFootCBatMostPoint95:result.C_over_B.footprintBytes.geometricMeanRatio<=limit.geometricFootprint_C_over_B_atMost};
result.costGatePassed=Object.values(result.costGate).every(Boolean);
console.log(JSON.stringify(result,null,2));
